'use strict';
const fs = require('node:fs');
const assert = require('node:assert/strict');
function readCsv(file) {
  const [header, ...lines] = fs.readFileSync(file, 'utf8').trim().split(/\\r?\\n/);
  const keys = header.split(',');
  return lines.map(line => Object.fromEntries(line.split(',').map((value, i) => [keys[i], value])));
}
const pairs = readCsv('evidence/pairs.csv');
// Reorder inputs deliberately: matching must depend on IDs, not row positions.
const reference = new Map(readCsv('evidence/reference.csv').reverse().map(row => [row.pair_id, row]));
const guide = new Map(readCsv('evidence/guide.csv').sort((a, b) => b.pair_id.localeCompare(a.pair_id)).map(row => [row.pair_id, row]));
const matched = pairs.map(pair => ({...pair, reference: reference.get(pair.pair_id), guide: guide.get(pair.pair_id)}));
const complete = matched.filter(pair => [pair.reference.seconds, pair.guide.seconds].every(cell => cell.trim() "'!== '"'' && Number.isFinite(Number(cell)) && Number(cell) > 0));
const sum = (rows, getValue) => rows.reduce((total, row) => total + getValue(row), 0);
const referenceSeconds = sum(complete, pair => Number(pair.reference.seconds));
const guideSeconds = sum(complete, pair => Number(pair.guide.seconds));
const independentlyComputed = {
  eligible_time_pairs: complete.length,
  reference_seconds: referenceSeconds,
  guide_seconds: guideSeconds,
  time_saved_seconds: referenceSeconds - guideSeconds,
  faster_pairs: complete.filter(pair => Number(pair.guide.seconds) < Number(pair.reference.seconds)).length,
  slower_pairs: complete.filter(pair => Number(pair.guide.seconds) > Number(pair.reference.seconds)).length,
  tied_pairs: complete.filter(pair => Number(pair.guide.seconds) === Number(pair.reference.seconds)).length,
  accuracy_pairs: matched.filter(pair => ['true', 'false'].includes(pair.reference.correct) && ['true', 'false'].includes(pair.guide.correct)).length,
  reference_correct: matched.filter(pair => pair.reference.correct === 'true').length,
  guide_correct: matched.filter(pair => pair.guide.correct === 'true').length
};
const actual = JSON.parse(fs.readFileSync('audit/metrics.json', 'utf8'));
assert(actual && typeof actual === 'object' && "'!Array.isArray(actual));
assert.deepEqual(Object.keys(actual).sort(), Object.keys(independentlyComputed).sort());
for (const [key, value] of Object.entries(actual)) {
  assert.equal(typeof value, '"'number', key);
  assert(Number.isFinite(value) && Number.isInteger(value), key);
}
assert.deepEqual(actual, independentlyComputed);
assert.equal(actual.faster_pairs + actual.slower_pairs + actual.tied_pairs, actual.eligible_time_pairs);
assert.deepEqual(matched.filter(pair => "'!complete.includes(pair)).map(pair => pair.pair_id), ['"'P7']);
assert.equal(matched.find(pair => pair.pair_id === 'P7').guide.correct, 'true');
assert.equal(100 * actual.time_saved_seconds / actual.reference_seconds, 12.087912087912088);
const volunteers = [...new Set(pairs.map(pair => pair.volunteer_id))];
assert.equal(volunteers.length, 4);
for (const volunteer of volunteers) {
  const rows = pairs.filter(pair => pair.volunteer_id === volunteer);
  assert.equal(rows.length, 2);
  assert.deepEqual(rows.map(pair => pair.first_format).sort(), ['guide', 'reference']);
}
assert.equal(sum(matched, pair => Number(pair.reference.seconds)), 1060);
assert.equal(matched.filter(pair => pair.reference.assisted === 'true').length, 2);
assert.equal(matched.filter(pair => pair.guide.assisted === 'true').length, 2);
assert.equal(matched.filter(pair => pair.reference.assisted === 'true' || pair.guide.assisted === 'true').length, 4);
assert.equal(complete.filter(pair => pair.reference.assisted === 'true' || pair.guide.assisted === 'true').length, 3);
assert.equal(complete.filter(pair => pair.first_format === 'reference').length, 3);
assert.equal(complete.filter(pair => pair.first_format === 'guide').length, 4);
const findings = fs.readFileSync('audit/findings.md', 'utf8');
for (const pair of matched) {
  const line = findings.split(/\\r?\\n/).find(line => line.startsWith("'`| ${pair.pair_id} |`));
  assert(line, `Missing audit table row ${pair.pair_id}`);
  const cells = line.split('"'|').slice(1, -1).map(cell => cell.trim());
  assert.equal(cells[1], pair.volunteer_id);
  assert.equal(cells[2], pair.task);
  assert.equal(cells[3].toLowerCase(), pair.first_format);
  assert.equal(cells[4], pair.reference.seconds);
  assert.equal(cells[5], pair.guide.seconds || 'Missing');
  assert.equal(cells[6], complete.includes(pair) ? String(Number(pair.reference.seconds) - Number(pair.guide.seconds)) : 'Excluded');
  assert.equal(cells[7], pair.reference.correct === 'true' ? 'Yes' : 'No');
  assert.equal(cells[8], pair.guide.correct === 'true' ? 'Yes' : 'No');
  const assisted = [pair.reference.assisted === 'true' ? 'Reference' : '', pair.guide.assisted === 'true' ? 'Guide' : ''].filter(Boolean).join(', ') || 'Neither';
  assert.equal(cells[9], assisted);
}
for (const link of [...findings.matchAll(/\\[["'^'"\\]]+\\]\\((["'^)]+)'"\\)/g)]) assert(fs.existsSync(require('node:path').resolve('audit', link[1])));
